query GetMergedPositions {
  mergedPositions {
    id
    owner
    liquidity
  }
}

ef8bf03e2cf59a987c837663a925f988f45f94dc:
query GetSushiswapPositions {
  positions(
    first: 100
    orderBy: liquidity
    orderDirection: desc
    where: {liquidity_gt: "0"}
  ) {
    id
    account {
      id
    }
    liquidity
  }
}

a4b16850e524c781b004ef7e51ee356ae58cf8b8:
query GetHighLiquidityUniswapPools {
  pools(
    first: 100
    orderBy: totalValueLockedUSD
    orderDirection: desc
    where: {totalValueLockedUSD_gt: "1000000"}
  ) {
    id
    token0 {
      id
      symbol
      decimals
    }
    token1 {
      id
      symbol
      decimals
    }
    totalValueLockedUSD
    totalValueLockedToken0
    totalValueLockedToken1
    feeTier
    liquidity
    token0Price
    token1Price
    poolHourData(first: 24, orderBy: periodStartUnix, orderDirection: desc) {
      periodStartUnix
      volumeUSD
      tvlUSD
    }
  }
}

query GetUniswapPositions {
  positions(
    first: 100
    orderBy: liquidity
    orderDirection: desc
    where: {liquidity_gt: "0"}
  ) {
    id
    owner
    liquidity
  }
}

query GetUniswapMetrics {
  factories(first: 1) {
    id
    poolCount
    totalValueLockedUSD
    totalFeesUSD
  }
  bundles(first: 1) {
    ethPriceUSD
  }
}
